<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
require __DIR__ . '/app/layout.php';

$action = $_GET['action'] ?? '';
if ($action === 'logout') { session_destroy(); header('Location: index.php?page=login'); exit; }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $intent = $_POST['intent'] ?? '';
    if ($intent === 'login') {
        $st = db()->prepare('SELECT id, password_hash FROM users WHERE email = :email');
        $st->execute(['email' => strtolower(trim($_POST['email'] ?? ''))]); $account = $st->fetch();
        if ($account && password_verify($_POST['password'] ?? '', $account['password_hash'])) { session_regenerate_id(true); $_SESSION['user_id'] = $account['id']; redirect('dashboard'); }
        flash('danger', 'E-mail ou senha inválidos.'); redirect('login');
    }
    if ($intent === 'register') {
        $email = strtolower(trim($_POST['email'] ?? ''));
        $contentName = trim($_POST['content_name'] ?? '');
        $datingName = trim($_POST['dating_name'] ?? '');
        $birthDate = $_POST['birth_date'] ?? '';
        if (!filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($_POST['password'] ?? '') < 10 || !$contentName || !$datingName || !$birthDate) {
            flash('danger', 'Preencha os campos e use uma senha de pelo menos 10 caracteres.'); redirect('register');
        }
        try {
            db()->beginTransaction();
            $st = db()->prepare('INSERT INTO users (email,password_hash,birth_date) VALUES (:email,:password,:birth) RETURNING id');
            $st->execute(['email'=>$email, 'password'=>password_hash($_POST['password'], PASSWORD_DEFAULT), 'birth'=>$birthDate]);
            $newId = (int) $st->fetchColumn();
            db()->prepare('INSERT INTO content_profiles (user_id,display_name) VALUES (:id,:name)')->execute(['id'=>$newId,'name'=>$contentName]);
            db()->prepare('INSERT INTO relationship_profiles (user_id,display_name,bio,city,is_active) VALUES (:id,:name,:bio,:city,:active)')->execute(['id'=>$newId,'name'=>$datingName,'bio'=>trim($_POST['dating_bio'] ?? ''),'city'=>trim($_POST['city'] ?? ''),'active'=>isset($_POST['dating_enabled'])]);
            db()->prepare('UPDATE user_settings SET content_enabled=:content,dating_enabled=:dating,integration_enabled=:integration,visitor_identity_consent=:visitor WHERE user_id=:id')->execute(['content'=>isset($_POST['content_enabled']),'dating'=>isset($_POST['dating_enabled']),'integration'=>isset($_POST['integration_enabled']),'visitor'=>isset($_POST['visitor_identity_consent']),'id'=>$newId]);
            db()->commit(); session_regenerate_id(true); $_SESSION['user_id']=$newId; flash('success','Conta criada. Você decide quais experiências quer habilitar.'); redirect('dashboard');
        } catch (Throwable $exception) { if (db()->inTransaction()) db()->rollBack(); flash('danger','Não foi possível criar a conta. O e-mail pode já estar em uso.'); redirect('register'); }
    }
    $user = require_login(); $id = (int) $user['id'];
    if ($intent === 'settings') {
        db()->prepare('UPDATE user_settings SET content_enabled=:c, dating_enabled=:d, integration_enabled=:i, visitor_identity_consent=:v WHERE user_id=:id')->execute(['c'=>isset($_POST['content_enabled']),'d'=>isset($_POST['dating_enabled']),'i'=>isset($_POST['integration_enabled']),'v'=>isset($_POST['visitor_identity_consent']),'id'=>$id]);
        flash('success', 'Preferências atualizadas. A integração exige o consentimento explícito de ambas as partes.'); redirect('settings');
    }
    if ($intent === 'close_account') {
        if (($_POST['confirmation'] ?? '') !== 'ENCERRAR') {
            flash('danger', 'Digite ENCERRAR para confirmar o encerramento da conta.'); redirect('settings');
        }
        db()->prepare("UPDATE users SET status='closed' WHERE id=:id")->execute(['id'=>$id]);
        session_destroy(); session_start(); flash('success','Sua conta foi encerrada e novas interações foram interrompidas.'); redirect('login');
    }
    if ($intent === 'publish') {
        db()->prepare('INSERT INTO content_posts (producer_id,title,description,access_type,is_adult,visibility,status) VALUES (:id,:title,:description,:access,:adult,:visibility,\'published\')')->execute(['id'=>$id,'title'=>trim($_POST['title']),'description'=>trim($_POST['description']),'access'=>$_POST['access_type'],'adult'=>isset($_POST['is_adult']),'visibility'=>$_POST['visibility']]);
        flash('success', 'Publicação criada.'); redirect('content');
    }
    if ($intent === 'like') {
        $target=(int)$_POST['target_id'];
        if (eligible_for_interaction($id,$target)) { db()->prepare("INSERT INTO relationship_interests (from_user_id,to_user_id,origin,status) VALUES (:from,:to,:origin,'pending') ON CONFLICT (from_user_id,to_user_id) DO UPDATE SET status='pending', created_at=NOW()") ->execute(['from'=>$id,'to'=>$target,'origin'=>$_POST['origin']]); flash('success','Interesse registrado. Um match só acontece mediante reciprocidade.'); }
        else flash('warning','Esta interação não está elegível no momento.');
        redirect($_POST['return_page'] ?? 'discover');
    }
    if ($intent === 'respond') {
        $interest=(int)$_POST['interest_id']; $decision=$_POST['decision'];
        $st=db()->prepare('SELECT * FROM relationship_interests WHERE id=:id AND to_user_id=:user AND status=\'pending\''); $st->execute(['id'=>$interest,'user'=>$id]); $item=$st->fetch();
        if ($item && $decision === 'like' && eligible_for_interaction($id,(int)$item['from_user_id'])) { db()->prepare("UPDATE relationship_interests SET status='accepted', responded_at=NOW() WHERE id=:id")->execute(['id'=>$interest]); db()->prepare('INSERT INTO matches (user_low_id,user_high_id,origin) VALUES (LEAST(:a,:b),GREATEST(:a,:b),:origin) ON CONFLICT (user_low_id,user_high_id) DO NOTHING')->execute(['a'=>$id,'b'=>$item['from_user_id'],'origin'=>$item['origin']]); flash('success','Match criado com consentimento recíproco.'); }
        elseif ($item && $decision === 'dismiss') { db()->prepare("UPDATE relationship_interests SET status='dismissed', responded_at=NOW() WHERE id=:id")->execute(['id'=>$interest]); flash('secondary','Oportunidade encerrada sem notificar uma rejeição explícita.'); }
        redirect('matches');
    }
    if ($intent === 'block') { $target=(int)$_POST['target_id']; db()->prepare('INSERT INTO blocks (blocker_id,blocked_id) VALUES (:a,:b) ON CONFLICT DO NOTHING')->execute(['a'=>$id,'b'=>$target]); db()->prepare("UPDATE matches SET status='blocked', ended_at=NOW() WHERE user_low_id=LEAST(:a,:b) AND user_high_id=GREATEST(:a,:b)")->execute(['a'=>$id,'b'=>$target]); db()->prepare("UPDATE relationship_interests SET status='invalidated' WHERE (from_user_id=:a AND to_user_id=:b) OR (from_user_id=:b AND to_user_id=:a)")->execute(['a'=>$id,'b'=>$target]); flash('success','Bloqueio aplicado; interesses e matches foram interrompidos.'); redirect('matches'); }
    if ($intent === 'message') { $matchId=(int)$_POST['match_id']; $body=trim($_POST['body'] ?? ''); if (mb_strlen($body) > 2000) $body=mb_substr($body,0,2000); if ($body) { try { db()->prepare('INSERT INTO match_messages (match_id,sender_id,body) VALUES (:match,:sender,:body)')->execute(['match'=>$matchId,'sender'=>$id,'body'=>$body]); } catch (PDOException) { flash('danger','Esta conversa não está disponível.'); } } header('Location: index.php?page=conversations&match='.$matchId); exit; }
    if ($intent === 'access_content') {
        $postId=(int)$_POST['post_id'];
        $st=db()->prepare("SELECT cp.* FROM content_posts cp JOIN users u ON u.id=cp.producer_id WHERE cp.id=:post AND cp.status='published' AND cp.access_type='free' AND NOT cp.is_adult");
        $st->execute(['post'=>$postId]); $post=$st->fetch();
        if ($post) { db()->prepare('INSERT INTO content_accesses (content_id,viewer_id,is_valid) VALUES (:post,:viewer,true)')->execute(['post'=>$postId,'viewer'=>$id]); header('Location: index.php?page=post&id='.$postId); exit; }
        flash('warning','Este conteúdo requer uma condição de acesso que ainda não está disponível neste MVP.'); redirect('feed');
    }
    if ($intent === 'report') {
        $target=(int)($_POST['reported_user_id'] ?? 0); $category=$_POST['category'] ?? ''; $details=trim($_POST['details'] ?? '');
        if (in_array($category,['assédio','fraude','conteúdo impróprio','outro'],true) && $details) { db()->prepare('INSERT INTO reports (reporter_id,reported_user_id,category,details) VALUES (:reporter,:target,:category,:details)')->execute(['reporter'=>$id,'target'=>$target?:null,'category'=>$category,'details'=>$details]); flash('success','Denúncia recebida. A equipe autorizada fará a triagem.'); }
        else flash('danger','Informe a categoria e os detalhes da denúncia.'); redirect('report');
    }
    if ($intent === 'moderate_report') {
        require_admin(); $reportId=(int)$_POST['report_id']; $status=$_POST['status'] ?? '';
        if (in_array($status,['reviewing','resolved','dismissed'],true)) {
            db()->prepare('UPDATE reports SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$reportId]);
            flash('success','Estado da denúncia atualizado.');
        }
        redirect('moderation');
    }
    if ($intent === 'restrict_user') {
        require_admin(); $target=(int)$_POST['target_id']; $status=$_POST['status'] ?? '';
        if (in_array($status,['active','suspended'],true) && $target !== $id) {
            db()->prepare('UPDATE users SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$target]);
            flash('success','Estado da conta atualizado.');
        }
        redirect('moderation');
    }
}

$page = $_GET['page'] ?? (current_user() ? 'dashboard' : 'login');
if ($page === 'login') { layout_start('Entrar', null); ?>
<div class="row justify-content-center pt-5"><div class="col-md-5"><div class="card shadow"><div class="card-body p-5"><h2 class="text-center text-primary"><i class="bi bi-heart-fill"></i> MyMatch</h2><p class="text-center text-muted">Conteúdo e relacionamentos, com escolhas independentes.</p><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="intent" value="login"><div class="mb-3"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Senha</label><input class="form-control" type="password" name="password" required></div><button class="btn btn-primary w-100">Entrar</button></form><p class="small text-muted mt-4 mb-0">Ainda não possui conta? <a href="index.php?page=register">Criar conta</a><br>Dados de demonstração: ana@mymatch.local / mymatch123.</p></div></div></div></div><?php layout_end(); exit; }
if ($page === 'register') { layout_start('Criar conta', null); ?>
