if ($page === 'discover' || $page === 'visitors') { $visitor=$page==='visitors'; $sql=$visitor ? "SELECT DISTINCT rp.user_id, rp.display_name, rp.bio, rp.city FROM content_accesses a JOIN content_posts cp ON cp.id=a.content_id JOIN relationship_profiles rp ON rp.user_id=a.viewer_id JOIN user_settings s ON s.user_id=a.viewer_id WHERE cp.producer_id=:id AND a.is_valid AND s.integration_enabled AND s.visitor_identity_consent" : "SELECT rp.user_id,rp.display_name,rp.bio,rp.city FROM relationship_profiles rp JOIN user_settings s ON s.user_id=rp.user_id WHERE rp.user_id<>:id AND rp.is_active AND s.dating_enabled AND NOT EXISTS (SELECT 1 FROM blocks b WHERE (b.blocker_id=:id AND b.blocked_id=rp.user_id) OR (b.blocker_id=rp.user_id AND b.blocked_id=:id))"; $st=db()->prepare($sql);$st->execute(['id'=>$id]);$profiles=$st->fetchAll(); layout_start($visitor?'Visitantes elegíveis':'Descobrir pessoas',$user); ?>
<div class="alert alert-info"><i class="bi bi-info-circle"></i> <?= $visitor?'Somente visitas válidas, consentidas e elegíveis aparecem aqui.':'Perfis de relacionamento não dependem de consumo de conteúdo.' ?></div><div class="row g-3"><?php foreach($profiles as $p): ?><div class="col-md-4"><div class="card h-100"><div class="card-body"><h4><?= e($p['display_name']) ?></h4><p class="text-muted"><i class="bi bi-geo-alt"></i> <?= e($p['city'] ?: 'Localização não informada') ?></p><p><?= e($p['bio']) ?></p></div><div class="card-footer d-flex gap-2"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="intent" value="like"><input type="hidden" name="target_id" value="<?= $p['user_id'] ?>"><input type="hidden" name="origin" value="<?= $visitor?'content_visit':'discovery' ?>"><input type="hidden" name="return_page" value="<?= $page ?>"><button class="btn btn-outline-danger"><i class="bi bi-heart"></i> Curtir</button></form></div></div></div><?php endforeach; if(!$profiles): ?><div class="col"><div class="card card-body text-muted">Nenhum perfil elegível agora.</div></div><?php endif; ?></div><?php layout_end(); exit; }
if ($page === 'matches') { $st=db()->prepare("SELECT i.*,rp.display_name FROM relationship_interests i JOIN relationship_profiles rp ON rp.user_id=i.from_user_id WHERE i.to_user_id=:id AND i.status='pending'");$st->execute(['id'=>$id]);$pending=$st->fetchAll(); $st=db()->prepare("SELECT m.*,rp.display_name, rp.user_id FROM matches m JOIN relationship_profiles rp ON rp.user_id=CASE WHEN m.user_low_id=:id THEN m.user_high_id ELSE m.user_low_id END WHERE (:id IN (m.user_low_id,m.user_high_id)) AND m.status='active'");$st->execute(['id'=>$id]);$matches=$st->fetchAll(); layout_start('Matches e oportunidades',$user); ?>
<div class="row g-3"><div class="col-lg-6"><div class="card"><div class="card-header"><h3 class="card-title">Oportunidades pendentes</h3></div><div class="list-group list-group-flush"><?php foreach($pending as $p): ?><div class="list-group-item"><strong><?=e($p['display_name'])?></strong> quer conhecer você.<div class="mt-2 d-flex gap-2"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="respond"><input type="hidden" name="interest_id" value="<?= $p['id'] ?>"><input type="hidden" name="decision" value="like"><button class="btn btn-sm btn-danger">Curtir de volta</button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="respond"><input type="hidden" name="interest_id" value="<?= $p['id'] ?>"><input type="hidden" name="decision" value="dismiss"><button class="btn btn-sm btn-outline-secondary">Agora não</button></form></div></div><?php endforeach; if(!$pending): ?><div class="list-group-item text-muted">Sem oportunidades pendentes.</div><?php endif;?></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header"><h3 class="card-title">Seus matches</h3></div><div class="list-group list-group-flush"><?php foreach($matches as $m): ?><div class="list-group-item d-flex justify-content-between align-items-center"><span><span class="match-dot me-2"></span><?=e($m['display_name'])?></span><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="block"><input type="hidden" name="target_id" value="<?= $m['user_id'] ?>"><button class="btn btn-sm btn-outline-danger">Bloquear</button></form></div><?php endforeach; if(!$matches): ?><div class="list-group-item text-muted">Ainda não há matches.</div><?php endif;?></div></div></div></div><?php layout_end(); exit; }
if ($page === 'conversations') { $st=db()->prepare("SELECT m.id,rp.display_name,rp.user_id FROM matches m JOIN relationship_profiles rp ON rp.user_id=CASE WHEN m.user_low_id=:id THEN m.user_high_id ELSE m.user_low_id END WHERE :id IN (m.user_low_id,m.user_high_id) AND m.status='active' ORDER BY m.created_at DESC");$st->execute(['id'=>$id]);$matchList=$st->fetchAll();$matchId=(int)($_GET['match'] ?? ($matchList[0]['id'] ?? 0));$messages=[];$selected=null;foreach($matchList as $match){if((int)$match['id']===$matchId)$selected=$match;}if($selected){$st=db()->prepare('SELECT mm.*,rp.display_name FROM match_messages mm JOIN relationship_profiles rp ON rp.user_id=mm.sender_id WHERE mm.match_id=:match ORDER BY mm.created_at');$st->execute(['match'=>$matchId]);$messages=$st->fetchAll();}layout_start('Conversas',$user); ?>
<div class="alert alert-info"><i class="bi bi-shield-check"></i> Conversas são liberadas apenas após match ativo. Você pode bloquear a qualquer momento.</div><div class="row"><div class="col-md-4"><div class="list-group mb-3"><?php foreach($matchList as $match): ?><a class="list-group-item list-group-item-action <?= $matchId===$match['id']?'active':'' ?>" href="index.php?page=conversations&match=<?= $match['id'] ?>"><i class="bi bi-chat-dots me-2"></i><?=e($match['display_name'])?></a><?php endforeach;if(!$matchList):?><div class="list-group-item text-muted">Nenhum match ativo.</div><?php endif;?></div></div><div class="col-md-8"><div class="card"><div class="card-header"><strong><?=e($selected['display_name'] ?? 'Selecione uma conversa')?></strong></div><div class="card-body" style="min-height:300px"><?php foreach($messages as $message): ?><div class="mb-3 <?= (int)$message['sender_id']===$id?'text-end':'' ?>"><span class="badge <?= (int)$message['sender_id']===$id?'text-bg-primary':'text-bg-secondary' ?> p-2 text-wrap" style="max-width:75%"><?=e($message['body'])?></span><div class="small text-muted mt-1"><?=e($message['display_name'])?> · <?=e($message['created_at'])?></div></div><?php endforeach;if($selected&&!$messages):?><p class="text-muted">Comece a conversa com respeito.</p><?php endif;?></div><?php if($selected):?><form method="post" class="card-footer"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="message"><input type="hidden" name="match_id" value="<?=$matchId?>"><div class="input-group"><input class="form-control" name="body" maxlength="2000" placeholder="Escreva uma mensagem" required><button class="btn btn-primary">Enviar</button></div></form><?php endif;?></div></div></div><?php layout_end(); exit; }
if ($page === 'report') { $st=db()->prepare('SELECT user_id,display_name FROM relationship_profiles WHERE user_id<>:id ORDER BY display_name');$st->execute(['id'=>$id]);$profiles=$st->fetchAll();layout_start('Denunciar uma situação',$user); ?>
<div class="row"><div class="col-lg-8"><div class="card"><form method="post"><div class="card-body"><p class="text-muted">A denúncia será acessada apenas por responsáveis autorizados para triagem e moderação. Não informaremos a identidade do denunciante à pessoa denunciada.</p><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="report"><div class="mb-3"><label class="form-label">Pessoa envolvida (opcional)</label><select class="form-select" name="reported_user_id"><option value="">Não se aplica / conteúdo geral</option><?php foreach($profiles as $profile):?><option value="<?=$profile['user_id']?>"><?=e($profile['display_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Categoria</label><select class="form-select" name="category" required><option value="">Selecione</option><option value="assédio">Assédio ou comportamento abusivo</option><option value="fraude">Fraude ou tentativa de golpe</option><option value="conteúdo impróprio">Conteúdo impróprio</option><option value="outro">Outro</option></select></div><div class="mb-3"><label class="form-label">O que aconteceu?</label><textarea class="form-control" name="details" rows="5" maxlength="5000" required></textarea></div></div><div class="card-footer"><button class="btn btn-danger"><i class="bi bi-flag"></i> Enviar denúncia</button></div></form></div></div></div><?php layout_end(); exit; }
if ($page === 'moderation') { require_admin(); $reports=db()->query("SELECT r.*, reporter.email AS reporter_email, target.email AS target_email FROM reports r JOIN users reporter ON reporter.id=r.reporter_id LEFT JOIN users target ON target.id=r.reported_user_id ORDER BY CASE r.status WHEN 'open' THEN 0 WHEN 'reviewing' THEN 1 ELSE 2 END,r.created_at DESC")->fetchAll(); layout_start('Triagem de moderação',$user); ?>
<div class="alert alert-warning"><i class="bi bi-shield-exclamation"></i> Acesso administrativo é registrado e deve ser limitado ao necessário para tratar cada incidente.</div><div class="card"><div class="card-header"><h3 class="card-title">Denúncias</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Data</th><th>Categoria</th><th>Envolvido</th><th>Detalhes</th><th>Estado</th><th>Ação</th></tr></thead><tbody><?php foreach($reports as $report):?><tr><td><?=e($report['created_at'])?></td><td><?=e($report['category'])?></td><td><?=e($report['target_email'] ?? 'Geral')?></td><td><?=e($report['details'])?></td><td><span class="badge text-bg-secondary"><?=e($report['status'])?></span></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="moderate_report"><input type="hidden" name="report_id" value="<?=$report['id']?>"><select name="status" class="form-select form-select-sm"><option value="reviewing">Em análise</option><option value="resolved">Resolvida</option><option value="dismissed">Descartada</option></select><button class="btn btn-sm btn-primary">Salvar</button></form><?php if($report['reported_user_id']):?><form method="post" class="mt-1"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="restrict_user"><input type="hidden" name="target_id" value="<?=$report['reported_user_id']?>"><input type="hidden" name="status" value="suspended"><button class="btn btn-sm btn-outline-danger">Suspender conta</button></form><?php endif;?></td></tr><?php endforeach;if(!$reports):?><tr><td colspan="6" class="text-muted">Nenhuma denúncia registrada.</td></tr><?php endif;?></tbody></table></div></div><?php layout_end(); exit; }
http_response_code(404); layout_start('Página não encontrada',$user); echo '<div class="alert alert-warning">Página não encontrada.</div>'; layout_end();
